def flatten(d: dict) -> dict:
    """Flatten one level of nested dicts, joining keys with a dot."""
    result = {}

    for key, value in d.items():
        if isinstance(value, dict):
            # Flatten the current level by creating new keys with '.' separator
            for sub_key, sub_value in value.items():
                flattened_key = f"{key}.{sub_key}"
                result[flattened_key] = sub_value
        else:
            # Non-dict values stay as they are at their original key
            result[key] = value

    return result
